static int i2c_read_sequential(uint8_t slave_address, uint16_t mem_address, uint8_t* data, uint16_t length){

	uint32_t timeout;
	uint32_t dummy;
	uint16_t index = 0U;
	uint16_t remaining = length;

	if(data == NULL){
		return -1;
	}
	if(length == 0U){
		return -2;
	}

	if(mem_address >= 32768U || length > (32768U - mem_address)){
		return -4;
	}

	I2C1_CR1 &= ~(1U << 11U);
	I2C1_CR1 |=  (1U << 10U);

	I2C1_CR1 |= (1U << 8U);

	timeout = 1000000U;

	while(!(I2C1_SR1 & 1U)){
		if(--timeout == 0U){
			return -2;
		}
	}

	I2C1_DR =(uint8_t)(slave_address << 1U);

	timeout = 1000000U;

	while(!(I2C1_SR1 & (1U << 1U))){
		if(I2C1_SR1 & (1U << 10U)){
			i2c_clear_af();
			I2C1_CR1 |= (1U << 9U);
			return -1;
		}
		if(--timeout == 0U){
			I2C1_CR1 |= (1U << 9U);
			return -2;
		}
	}

	dummy = I2C1_SR1;
	dummy = I2C1_SR2;
	(void)dummy;

	I2C1_DR =(uint8_t)((mem_address >> 8U) & (0xFFU));

	timeout = 1000000U;

	while(!(I2C1_SR1 & (1U << 7U))){
		if(I2C1_SR1 & (1U << 10U)){
			i2c_clear_af();
			I2C1_CR1 |= (1U << 9U);
			return -1;
		}
		if(--timeout == 0U){
			I2C1_CR1 |= (1U << 9U);
			return -2;
		}
	}

	I2C1_DR =(uint8_t)((mem_address & 0xFFU));

	timeout = 1000000U;

	while(!(I2C1_SR1 & (1U << 2U))){
		if(I2C1_SR1 & (1U << 10U)){
			i2c_clear_af();
			I2C1_CR1 |= (1U << 9U);
			return -1;
		}
		if(--timeout == 0U){
			I2C1_CR1 |= (1U << 9U);
			return -2;
		}
	}

	I2C1_CR1 |= (1U << 8U);

	timeout = 1000000U;

	while(!(I2C1_SR1 & 1U)){
		if(--timeout == 0U){
			I2C1_CR1 |= (1U << 9U);
			return -2;
		}
	}

	I2C1_DR =(uint8_t)((slave_address << 1U) | 1U);

	timeout = 1000000U;

	while(!(I2C1_SR1 & (1U << 1U))){
		if(I2C1_SR1 & (1U << 10U)){
			i2c_clear_af();
			I2C1_CR1 |= (1U << 9U);
			return -1;
		}
		if(--timeout == 0U){
			I2C1_CR1 |= (1U << 9U);
			return -2;
		}
	}

	if(length == 1U){
		I2C1_CR1 &= ~(1U << 10U);

		dummy = I2C1_SR1;
		dummy = I2C1_SR2;
		(void)dummy;

		I2C1_CR1 |= (1U << 9U);

		timeout = 1000000U;

		while(!(I2C1_SR1 & (1U << 6U))){
			if(--timeout == 0U){
				I2C1_CR1 |= (1U << 9U);
				I2C1_CR1 |= (1U << 10U);
				return -2;
			}
		}

		data[0] = I2C1_DR;

		I2C1_CR1 |= (1U << 10U);

		return 0;
	}

	if(length == 2U){
		I2C1_CR1 |= (1U << 11U);
		I2C1_CR1 &= ~(1U << 10U);

		dummy = I2C1_SR1;
		dummy = I2C1_SR2;
		(void)dummy;

		timeout = 1000000U;

		while(!(I2C1_SR1 & (1U << 2U))){
			if(--timeout == 0U){
				I2C1_CR1 |= (1U << 9U);
				I2C1_CR1 &= ~(1U << 11U);
				I2C1_CR1 |= (1U << 10U);
				return -2;
			}
		}

		I2C1_CR1 |= (1U << 9U);

		data[0] = I2C1_DR;
		data[1] = I2C1_DR;

		I2C1_CR1 &= ~(1U << 11U);
		I2C1_CR1 |= (1U << 10U);

		return 0;

	}

	I2C1_CR1 |= (1U << 10U);

	dummy = I2C1_SR1;
	dummy = I2C1_SR2;
	(void)dummy;

	while(remaining > 3U){

		timeout = 1000000U;

		while(!(I2C1_SR1 & (1U << 6U))){
			if(--timeout == 0U){
				I2C1_CR1 |= (1U << 9U);
				return -2;
			}
		}
		data[index] = I2C1_DR;
		index++;
		remaining--;
	}

	timeout = 1000000U;

	while(!(I2C1_SR1 & (1U << 2U))){
		if(--timeout == 0U){
			I2C1_CR1 |= (1U << 9U);
			return -2;
		}
	}

	I2C1_CR1 &= ~(1U << 10U);

	data[index] = I2C1_DR;
	index++;
	remaining--;

	timeout = 1000000U;

	while(!(I2C1_SR1 & (1U << 2U))){
		if(--timeout == 0U){
			I2C1_CR1 |= (1U << 9U);
			I2C1_CR1 |= (1U << 10U);
			return -2;
		}
	}

	I2C1_CR1 |= (1U << 9U);

	data[index] = I2C1_DR;
	index++;
	remaining--;

	data[index] = I2C1_DR;
	index++;
	remaining--;

	I2C1_CR1 |= (1U << 10U);

	return 0;
}

static int i2c_wait_write(uint8_t slave_address){

	uint32_t timeout = 1000000U;
	uint32_t retry = 1000U;
	uint32_t dummy;

	while(retry > 0U){

		timeout = 1000000U;

		I2C1_CR1 |= (1U << 8U);

		while((I2C1_SR1 & 1U) == 0U){
			if(timeout == 0U){
				I2C1_CR1 |= (1U << 9U);
				return -2;
			}
			timeout--;
		}

		I2C1_DR = ((uint32_t)slave_address << 1U);

		timeout = 1000000U;

		while(((I2C1_SR1 & (1U << 1U)) == 0U) && ((I2C1_SR1 & (1U << 10U)) == 0U)){
			if(timeout == 0U){
				I2C1_CR1 |= (1U << 9U);
				return -2;
			}
			timeout--;
		}

		if((I2C1_SR1 & (1U << 1U)) != 0U){
			dummy = I2C1_SR1;
			dummy = I2C1_SR2;
			(void)dummy;

			I2C1_CR1 |= (1U << 9U);

			return 0;
		}
		else if((I2C1_SR1 & (1U << 10U)) != 0U){
			i2c_clear_af();
			I2C1_CR1 |= (1U << 9U);
			retry--;
		}
	}
	return -2;
}

static int i2c_probe(uint8_t slave_address)
{
    uint32_t timeout = 1000000U;
    uint32_t dummy;

    I2C1_CR1 |= (1U << 8U);

    while((I2C1_SR1 & 1U) == 0U){
    	if(timeout == 0U){
    		I2C1_CR1 |= (1U << 9U);
    		return -2;
    	}
    	timeout--;
    }

    I2C1_DR = ((uint32_t)(slave_address) << 1U);

    timeout = 1000000U;

    while(((I2C1_SR1 & (1U << 1U)) == 0U) && ((I2C1_SR1 & (1U << 10U)) == 0U)){
    	if(timeout == 0U){
    		I2C1_CR1 |= (1U << 9U);
    		return -2;
    	}
    	timeout--;
    }

    if((I2C1_SR1 & (1U << 1U)) != 0U){
    	dummy = I2C1_SR1;
    	dummy = I2C1_SR2;
    	(void)dummy;

    	I2C1_CR1 |= (1U << 9U);

    	return 0;
    }
    else if((I2C1_SR1 & (1U << 10U)) != 0U){
    	i2c_clear_af();
    	I2C1_CR1 |= (1U << 9U);

    	return -1;
    }
    return -2;
}

static volatile int verify_result = -2;

int main(void)
{
	volatile int page_write_result = 99;
	volatile int i2c_wait_write_result = 99;
	volatile int read_result = 99;

	uint8_t tx_data[EEPROM_TEST_LEN] = {0x11U, 0x22U, 0x33U, 0x44U};
	uint8_t rx_data[EEPROM_TEST_LEN] = {0};


	gpio_init();
	i2c_init();

	page_write_result = i2c_write_page(
	    EEPROM_I2C_ADDR, EEPROM_TEST_ADDR, tx_data, EEPROM_TEST_LEN);

	if(page_write_result == 0){
		i2c_wait_write_result = i2c_wait_write(EEPROM_I2C_ADDR);
	}

	if(i2c_wait_write_result == 0){
		read_result = i2c_read_sequential(EEPROM_I2C_ADDR, EEPROM_TEST_ADDR, rx_data, EEPROM_TEST_LEN);
	}

	if(read_result == 0){
		verify_result = 0;

		for (uint16_t i = 0U; i < EEPROM_TEST_LEN; i++) {
		    if (rx_data[i] != tx_data[i]) {
		        verify_result = -1;
		        break;
		    }
		}
	}

    for(;;);
}
